#!/bin/bash
# ============================================================
# SIEMPRIA CONTEO v9.1 - Script Auto-Contenido
# ============================================================
# Ejecutar directamente en el servidor de produccion:
#   bash deploy_conteo_v91_auto.sh
# ============================================================
# Novedades v9.1:
#   - Heatmap automatico: nuevas camaras se configuran solas
#   - Al actualizar camara sin heatmap, se activa automaticamente
#   - Frontend modular: App.jsx + 14 componentes en src/conteo/
#   - Boton salir + tecla ESC en Modo Presentacion
# ============================================================

set -e

CONTEO_DIR="/opt/siempria-conteo"
BACKUP_DIR="$CONTEO_DIR/backups/$(date +%Y%m%d_%H%M%S)"
SERVICE_NAME="siempria-conteo"
TMPDIR="$(mktemp -d)"

echo "============================================"
echo "  SIEMPRIA CONTEO v9.1 - Despliegue Auto"
echo "============================================"
echo ""

# 1. Extraer payload embebido
echo "[1/6] Extrayendo archivos..."
PAYLOAD=""
echo "$PAYLOAD" | base64 -d | tar xzf - -C "$TMPDIR"
echo "   Archivos extraidos en $TMPDIR"

# 2. Backup
echo "[2/6] Creando backup..."
mkdir -p "$BACKUP_DIR"
cp "$CONTEO_DIR/backend/routes/cameras.py" "$BACKUP_DIR/cameras.py.bak" 2>/dev/null || true
cp "$CONTEO_DIR/frontend/src/App.jsx" "$BACKUP_DIR/App.jsx.bak" 2>/dev/null || true
[ -d "$CONTEO_DIR/frontend/src/conteo" ] && cp -r "$CONTEO_DIR/frontend/src/conteo" "$BACKUP_DIR/conteo_bak" 2>/dev/null || true
[ -d "$CONTEO_DIR/frontend/build" ] && cp -r "$CONTEO_DIR/frontend/build" "$BACKUP_DIR/frontend_build" 2>/dev/null || true
echo "   Backup en: $BACKUP_DIR"

# 3. Actualizar Backend
echo "[3/6] Actualizando backend..."
cp "$TMPDIR/cameras.py" "$CONTEO_DIR/backend/routes/cameras.py"
echo "   cameras.py actualizado (heatmap_profile automatico)"

# 4. Actualizar Frontend
echo "[4/6] Actualizando frontend..."
cp "$TMPDIR/App.jsx" "$CONTEO_DIR/frontend/src/App.jsx"

mkdir -p "$CONTEO_DIR/frontend/src/conteo/views"
for f in constants.js shared.js LoginPage.js Dashboard.js; do
    cp "$TMPDIR/$f" "$CONTEO_DIR/frontend/src/conteo/$f"
done
for f in RealtimeView.js BrandView.js CenterView.js TrendsView.js CamerasView.js UsersView.js NOCView.js ExecutiveView.js PresentationMode.js HeatmapView.js; do
    cp "$TMPDIR/$f" "$CONTEO_DIR/frontend/src/conteo/views/$f"
done
echo "   Frontend modular: 1 wrapper + 14 componentes"

# 5. Build frontend
echo "[5/6] Compilando frontend..."
cd "$CONTEO_DIR/frontend"
npm run build 2>&1 | tail -5
echo "   Frontend compilado"

# 6. Reiniciar servicio
echo "[6/6] Reiniciando servicio..."
sudo systemctl restart "$SERVICE_NAME" 2>/dev/null || sudo systemctl restart siempria-conteo.service 2>/dev/null || true
sleep 3

# Limpiar
rm -rf "$TMPDIR"

# Verificar
if sudo systemctl is-active --quiet "$SERVICE_NAME" 2>/dev/null; then
    echo ""
    echo "============================================"
    echo "  DESPLIEGUE v9.1 COMPLETADO"
    echo "============================================"
    echo "  Cambios:"
    echo "  - Heatmap auto en camaras nuevas/actualizadas"
    echo "  - Frontend modular (14 componentes)"
    echo "  - Boton salir + ESC en Presentacion"
    echo "  - Backup en: $BACKUP_DIR"
    echo "============================================"
else
    echo ""
    echo "[!] Servicio no activo. Revisa:"
    echo "    sudo systemctl status $SERVICE_NAME"
    echo "    sudo journalctl -u $SERVICE_NAME -n 50"
fi
